using System;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
namespace HarmonyLib{public class HarmonyMethod{public HarmonyMethod(MethodInfo m){}}public class Harmony{public List<string> Hooks=new();public void Patch(MethodInfo m,HarmonyMethod? p,HarmonyMethod? o,object? t,HarmonyMethod? f,object? il)=>Hooks.Add(m.DeclaringType!.Name+"."+m.Name);}}
namespace Il2CppSystem{public class Object{static long Next;public IntPtr Pointer{get;}=new(++Next);}}
namespace Il2CppSystem.Collections.Generic{public class List<T>:Il2CppSystem.Object{readonly System.Collections.Generic.List<T> V=new();public int Count=>V.Count;public T this[int n]=>V[n];public void Add(T v)=>V.Add(v);public bool Remove(T v)=>V.Remove(v);}}
namespace Polytopia.Data{public sealed class UnitAbility{public enum Type{AutoFreeze=20,Stomp=40,AutoHeal=41,Tentacles=44,AutoFlood=45,Algae=51}}public class UnitData:Il2CppSystem.Object{public string Name{get;set;}="warrior";public Il2CppSystem.Collections.Generic.List<UnitAbility.Type> unitAbilities{get;set;}=new();}}
public readonly struct WorldCoordinates{public int X{get;}public int Y{get;}public WorldCoordinates(int x,int y){X=x;Y=y;}}
public class PlayerState:Il2CppSystem.Object{public byte Id{get;set;}=1;}
public class UnitState:Il2CppSystem.Object{public uint id{get;set;}=1;public byte owner{get;set;}=1;public int health{get;set;}=100;public WorldCoordinates coordinates{get;set;}=new(0,0);public Polytopia.Data.UnitData UnitData{get;set;}=new();public bool Frozen,Bubbled,moved,attacked;public bool IsFreezable(GameState s,PlayerState p)=>!Frozen;}
public class TileData:Il2CppSystem.Object{public WorldCoordinates coordinates{get;set;}=new(0,0);public UnitState? unit{get;set;}public bool Ice,Flood,Algae,Allowed=true,Water=true;public bool IsFreezable(GameState s,PlayerState p,bool onlyOwned)=>Allowed&&!Ice;}
public class MapData:Il2CppSystem.Object{public System.Collections.Generic.List<TileData> Tiles{get;set;}=new();}
public class GameState:Il2CppSystem.Object{public MapData Map{get;set;}=new();public bool Admitted=true;public Il2CppSystem.Collections.Generic.List<ActionBase> ActionStack{get;set;}=new();public bool TryGetUnit(uint id,out UnitState? u){u=Map.Tiles.Select(t=>t.unit).FirstOrDefault(u=>u?.id==id);return u!=null;}}
public static class MapDataExtensions{public static TileData? GetTile(MapData map,WorldCoordinates p)=>map.Tiles.SingleOrDefault(t=>t.coordinates.X==p.X&&t.coordinates.Y==p.Y);}
public static class UnitDataExtensions{public static bool HasAbility(UnitState u,Polytopia.Data.UnitAbility.Type ability)=>Native.Items(u.UnitData.unitAbilities).Contains(ability);}
public static class ActionUtils{public static void CheckBubbleStep(TileData t,UnitState u,GameState s){u.Bubbled=true;}}
public abstract class ActionBase:Il2CppSystem.Object{public byte PlayerId{get;set;}=1;public abstract int GetActionType();}
public class MoveAction:ActionBase{public enum MoveReason{Command,Attack,Push}public uint UnitId{get;set;}=1;public MoveReason Reason{get;set;}public void Execute(GameState s){}public override int GetActionType()=>2;}
public class FreezeAreaAction:ActionBase{public WorldCoordinates Coordinates{get;set;}=new(0,0);public ushort Radius{get;set;}=1;public bool FreezeUnits{get;set;}=true;public bool OnlyOwnedTiles{get;set;}public void Execute(GameState s){}public override int GetActionType()=>17;}
public class FloodTileAction:ActionBase{public WorldCoordinates Coordinates{get;set;}=new(0,0);public void Execute(GameState s){}public override int GetActionType()=>87;}
public class BuildAction:ActionBase{public int Type{get;set;}=55;public override int GetActionType()=>1;}
namespace Deception.PolyModAdapter{
 internal static class NativeRegroupSession{internal static bool Enabled=true;internal static Dictionary<(long,uint),LedgerUnit> Rows=new();internal static bool Ready(object state)=>state is GameState s&&s.Admitted;internal static LedgerUnit? ReadIdentity(object state,uint id)=>Rows.GetValueOrDefault((Native.Pointer(state),id));}
 internal static class RecruitmentHooks{internal static Dictionary<string,Polytopia.Data.UnitData> Forms=new();internal static object Data(object state,string form)=>Forms[form];}
}
namespace Deception.Tests{
 public static class TerrainTests{
 static int Assertions;static readonly List<string> Cases=new();static void Check(bool value,string why){Assertions++;if(!value)throw new Exception(why);}static void Test(string name,Action a){try{a();Cases.Add(name);}catch(Exception e){throw new Exception(name,e);}}
 sealed record Rig(GameState State,UnitState Unit,TileData Tile,TileData Neighbor);
 static Rig Start(string actual="warrior",string apparent="mooni",bool mimic=false,bool masked=true){NativeApparentTerrain.Clear();NativeApparentTerrain.PendingDisguiseShed=null;NativeRegroupSession.Rows.Clear();RecruitmentHooks.Forms.Clear();foreach(var form in new[]{"warrior","mooni","gaami","crab","island","juggernaut"}){var d=new Polytopia.Data.UnitData{Name=form};foreach(int a in form is "mooni" or "gaami"?new[]{20}:form=="crab"?new[]{45}:form=="island"?new[]{40,51}:form=="juggernaut"?new[]{40}:Array.Empty<int>())d.unitAbilities.Add((Polytopia.Data.UnitAbility.Type)a);RecruitmentHooks.Forms[form]=d;}var s=new GameState();var u=new UnitState{UnitData=RecruitmentHooks.Forms[mimic?"warrior":actual],health=mimic?10:100};var tile=new TileData{unit=u};var neighbor=new TileData{coordinates=new(1,0),unit=new UnitState{id=2,owner=2,coordinates=new(1,0)}};s.Map.Tiles.AddRange(new[]{tile,neighbor});var appearance=new LedgerAppearance(apparent,new("Imperius","Default"),new("Imperius","Default"),new("Imperius","Default"),1,100,100,false,ApparentConcealment.Visible,-1,Array.Empty<string>());NativeRegroupSession.Rows[(Native.Pointer(s),1)]=new(2,1,true,mimic?LedgerActualKind.Mimic:LedgerActualKind.Genuine,masked,masked?appearance:null,PaidInvestmentKind.Known,3);return new(s,u,tile,neighbor);}
 static bool Ability(UnitState u,int ability){bool result=UnitDataExtensions.HasAbility(u,(Polytopia.Data.UnitAbility.Type)ability);NativeApparentTerrain.Ability(u,(Polytopia.Data.UnitAbility.Type)ability,ref result);return result;}
 static void Move(Rig r,int reason=0,Action? during=null){var a=new MoveAction{Reason=(MoveAction.MoveReason)reason};NativeApparentTerrain.BeforeMove(a,r.State,out var scope);try{if(reason!=2){if(Ability(r.Unit,20))r.State.ActionStack.Add(new FreezeAreaAction());if(Ability(r.Unit,45))r.State.ActionStack.Add(new FloodTileAction());if(Ability(r.Unit,51)&&r.Tile.Water&&!r.Tile.Algae)r.State.ActionStack.Add(new BuildAction());}during?.Invoke();NativeApparentTerrain.AfterMove(a,r.State,scope);}finally{NativeApparentTerrain.MoveFinished(null,scope);}}
 static void Freeze(Rig r,FreezeAreaAction action){NativeApparentTerrain.BeforeFreeze(action,r.State,out var scope);try{foreach(var tile in r.State.Map.Tiles){bool eligible=tile.IsFreezable(r.State,new(),false);NativeApparentTerrain.TileFreezable(r.State,ref eligible);if(eligible)tile.Ice=true;if(action.FreezeUnits&&tile.unit is UnitState unit){eligible=unit.IsFreezable(r.State,new());NativeApparentTerrain.UnitFreezable(r.State,ref eligible);if(eligible)unit.Frozen=true;}}}finally{NativeApparentTerrain.FreezeFinished(null,scope);}}
 static void Flood(Rig r,FloodTileAction action){NativeApparentTerrain.BeforeFlood(action,r.State,out var scope);try{r.Tile.Flood=true;if(r.Tile.unit is UnitState unit&&NativeApparentTerrain.BubbleStep(r.Tile,unit,r.State))ActionUtils.CheckBubbleStep(r.Tile,unit,r.State);}finally{NativeApparentTerrain.FloodFinished(null,scope);}}
 public static int Run(){try{
 Test("native-hooks-safe-reference-and-blittable-abi",()=>{var h=new HarmonyLib.Harmony();NativeApparentTerrain.Install(h);Check(h.Hooks.Count==7,"seven native boundary registrations remain unchanged");});
 foreach(bool mimic in new[]{false,true})foreach(string form in new[]{"mooni","gaami"})Test($"copied-freeze-grants-no-passive-{mimic}-{form}",()=>{var r=Start(apparent:form,mimic:mimic);var d=r.Unit.UnitData;Move(r);Check(!Native.Items(r.State.ActionStack).Any(),"disguise cannot queue freeze terrain or units");Check(!r.Tile.Ice&&!r.Neighbor.Ice&&!r.Unit.Frozen&&!r.Neighbor.unit!.Frozen,"no native mutation without a real passive");Check(ReferenceEquals(d,r.Unit.UnitData)&&r.Unit.health==(mimic?10:100)&&!r.Unit.moved&&!r.Unit.attacked,"true profiles, health and movement flags untouched");});
 foreach(string form in new[]{"mooni","gaami"})Test("genuine-freeze-survives-warrior-mask-"+form,()=>{var r=Start(form,"warrior");Move(r);var freeze=(FreezeAreaAction)Native.Items(r.State.ActionStack).Single();Check(freeze.FreezeUnits,"genuine unit freeze retained in serialized native action");Freeze(r,freeze);Check(r.Tile.Ice&&r.Neighbor.Ice&&r.Neighbor.unit!.Frozen,"all actual freeze effects survive unrelated mask");});
 Test("same-profile-native-ice-and-freeze",()=>{var r=Start("gaami","mooni");Move(r);Freeze(r,(FreezeAreaAction)Native.Items(r.State.ActionStack).Single());Check(r.Neighbor.Ice&&r.Neighbor.unit!.Frozen,"matching mask retains native body abilities");});
 Test("genuine-queued-freeze-survives-source-removal",()=>{var r=Start("gaami","warrior");Move(r);var original=(FreezeAreaAction)Native.Items(r.State.ActionStack).Single();var restored=new FreezeAreaAction{FreezeUnits=original.FreezeUnits};r.Tile.unit=null;Freeze(r,restored);Check(r.Neighbor.Ice&&r.Neighbor.unit!.Frozen,"queued native ability survives source removal and serialized field roundtrip");});
 Test("native-ineligible-ice-stays-ineligible",()=>{var r=Start("gaami","warrior");r.Neighbor.Allowed=false;Move(r);Freeze(r,(FreezeAreaAction)Native.Items(r.State.ActionStack).Single());Check(r.Tile.Ice&&!r.Neighbor.Ice,"native tile predicate is never widened");});
 foreach(bool mimic in new[]{false,true})Test("copied-crab-grants-no-flood-or-bubble-"+mimic,()=>{var r=Start(apparent:"crab",mimic:mimic);Move(r);Check(!Native.Items(r.State.ActionStack).Any()&&!r.Tile.Flood&&!r.Unit.Bubbled,"disguise supplies neither flood nor bubble");Check(NativeApparentTerrain.BubbleStep(r.Tile,r.Unit,r.State),"ordinary native environmental bubble callback remains available");});
 Test("genuine-crab-warrior-mask-keeps-flood-and-bubble",()=>{var r=Start("crab","warrior");Move(r);Flood(r,(FloodTileAction)Native.Items(r.State.ActionStack).Single());Check(r.Tile.Flood&&r.Unit.Bubbled,"genuine masked Crab retains its full native effect");});
 Test("genuine-crab-matching-mask-keeps-flood-and-bubble",()=>{var r=Start("crab","crab");Move(r);Flood(r,(FloodTileAction)Native.Items(r.State.ActionStack).Single());Check(r.Tile.Flood&&r.Unit.Bubbled,"matching appearance neither suppresses nor duplicates effects");});
 foreach(bool mimic in new[]{false,true})Test("copied-island-grants-no-algae-"+mimic,()=>{var r=Start(apparent:"island",mimic:mimic);Move(r);Check(!Native.Items(r.State.ActionStack).Any(),"no AlgaeSpawn or other build action from copied Island");Check(!Ability(r.Unit,40),"no copied Stomp");});
 Test("genuine-island-warrior-mask-keeps-algae-and-stomp",()=>{var r=Start("island","warrior");Move(r,during:()=>Check(Ability(r.Unit,40),"real Stomp remains native"));Check(Native.Items(r.State.ActionStack).Single() is BuildAction{Type:55},"native AlgaeSpawn55 retained, never fruit-producing Algae38");});
 foreach(int reason in new[]{0,1,2})Test("native-movement-reason-"+reason,()=>{var r=Start("gaami","warrior");Move(r,reason);Check(Native.Items(r.State.ActionStack).Count()==(reason==2?0:1),"native command/attack triggers retained; Push still has no trigger");});
 Test("exchange-has-no-movement-trigger",()=>{var r=Start(apparent:"crab");Check(!Ability(r.Unit,45)&&!Native.Items(r.State.ActionStack).Any(),"exchange creates no passive trigger");});
 foreach(string guard in new[]{"ordinary","foreign-state","dead","wrong-tile","other-unit"})Test("guard-"+guard,()=>{var r=Start(masked:guard!="ordinary");if(guard=="foreign-state")r.State.Admitted=false;if(guard=="dead")r.Unit.health=0;if(guard=="wrong-tile")r.Unit.coordinates=new(8,8);Move(r,during:()=>{if(guard=="other-unit")Check(!Ability(r.Neighbor.unit!,20),"other unit is never projected");});Check(!Native.Items(r.State.ActionStack).Any(),"no actual ability means no queued passive");});
 Test("preexisting-action-not-rewritten",()=>{var r=Start();var prior=new FreezeAreaAction();r.State.ActionStack.Add(prior);Move(r);Check(prior.FreezeUnits&&Native.Items(r.State.ActionStack).Count()==1,"unrelated native action stays exact and no borrowed child added");});
 Test("foreign-new-freeze-not-rewritten",()=>{var r=Start();var foreign=new FreezeAreaAction{PlayerId=2};Move(r,during:()=>r.State.ActionStack.Add(foreign));Check(foreign.FreezeUnits&&Native.Items(r.State.ActionStack).Count()==1,"another actor's nested native action is untouched");});
 Test("exception-and-clear-preserve-actual-capabilities",()=>{var r=Start("gaami","crab");var a=new MoveAction();NativeApparentTerrain.BeforeMove(a,r.State,out var scope);Check(Ability(r.Unit,20)&&!Ability(r.Unit,45),"active scope uses genuine freeze, not copied flood");var e=new Exception("native");Check(ReferenceEquals(e,NativeApparentTerrain.MoveFinished(e,scope))&&Ability(r.Unit,20)&&!Ability(r.Unit,45),"exception returned and native profile retained");NativeApparentTerrain.BeforeMove(a,r.State,out scope);NativeApparentTerrain.Clear();NativeApparentTerrain.MoveFinished(null,scope);Check(Ability(r.Unit,20)&&!Ability(r.Unit,45),"teardown cannot revive a projection");});
 foreach(string form in new[]{"mooni","crab","island"})Test("incompatible-move-has-no-borrowed-passive-"+form,()=>{var r=Start(apparent:form);NativeApparentTerrain.PendingDisguiseShed=(s,u)=>Native.Same(s,r.State)&&Native.Same(u,r.Unit);Move(r);Check(!Native.Items(r.State.ActionStack).Any(),"shed timing cannot re-enable copied terrain");});
 Test("incompatible-move-keeps-real-passive",()=>{var r=Start(actual:"gaami",apparent:"warrior");NativeApparentTerrain.PendingDisguiseShed=(s,u)=>Native.Same(s,r.State)&&Native.Same(u,r.Unit);Move(r);Check(Native.Items(r.State.ActionStack).Single() is FreezeAreaAction{FreezeUnits:true},"native actual passive still operates while shedding");});
 foreach(string form in new[]{"mooni","crab","island"})Test("true-mimic-carrier-cannot-reintroduce-terrain-"+form,()=>{var r=Start(apparent:form,mimic:true);r.Unit.UnitData=RecruitmentHooks.Forms[form];Move(r);Check(!Native.Items(r.State.ActionStack).Any(),"true Mimic scope vetoes terrain even if a carrier unexpectedly contains it");});
 Test("unmasked-genuine-passives-remain-native",()=>{var r=Start("gaami","warrior",masked:false);Move(r);Freeze(r,(FreezeAreaAction)Native.Items(r.State.ActionStack).Single());Check(r.Neighbor.Ice&&r.Neighbor.unit!.Frozen,"ordinary genuine native execution unchanged");});
 Test("nested-genuine-and-mimic-moves-restore-exact-source",()=>{var r=Start("gaami","crab");var other=new UnitState{id=2,owner=1,coordinates=new(1,0),UnitData=RecruitmentHooks.Forms["warrior"]};r.Neighbor.unit=other;var appearance=NativeRegroupSession.ReadIdentity(r.State,1)!.Appearance!;NativeRegroupSession.Rows[(Native.Pointer(r.State),2)]=new(3,2,true,LedgerActualKind.Mimic,true,appearance,PaidInvestmentKind.Known,3);NativeApparentTerrain.BeforeMove(new MoveAction(),r.State,out var outer);NativeApparentTerrain.BeforeMove(new MoveAction{UnitId=2},r.State,out var inner);Check(!Ability(other,45)&&Ability(r.Unit,20),"nested Mimic has no borrowed flood and genuine outer remains native");NativeApparentTerrain.MoveFinished(null,inner);Check(Ability(r.Unit,20)&&!Ability(r.Unit,45),"outer actual profile restored");NativeApparentTerrain.MoveFinished(null,outer);});
 NativeApparentTerrain.PendingDisguiseShed=null;
 Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Cases.Count,assertions=Assertions,tests=Cases,nativeGame="NOT RUN"}));return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
 }
}
